import { createHmac, timingSafeEqual } from "node:crypto";

export interface TokenClaims {
  sub: string;
  exp: number;
}

function decodeJson(segment: string): unknown {
  return JSON.parse(Buffer.from(segment, "base64url").toString("utf8"));
}

// Verify an HS256 JWT against `secret` and return its claims, or throw.
export function verifyToken(token: string, secret: string): TokenClaims {
  const parts = token.split(".");
  if (parts.length !== 3) throw new Error("malformed token");
  const [headerB64, payloadB64, signatureB64] = parts;

  // Pin the algorithm: never trust the header to pick it (blocks "none" / alg confusion).
  const header = decodeJson(headerB64) as { alg?: unknown };
  if (header?.alg !== "HS256") throw new Error("unsupported alg");

  const expected = createHmac("sha256", secret)
    .update(`${headerB64}.${payloadB64}`)
    .digest();
  const actual = Buffer.from(signatureB64, "base64url");
  if (actual.length !== expected.length || !timingSafeEqual(actual, expected)) {
    throw new Error("invalid signature");
  }

  const claims = decodeJson(payloadB64) as Partial<TokenClaims> | null;
  if (typeof claims?.sub !== "string" || typeof claims.exp !== "number") {
    throw new Error("invalid claims");
  }
  if (Math.floor(Date.now() / 1000) >= claims.exp) throw new Error("token expired");

  return { sub: claims.sub, exp: claims.exp };
}

